import { describe, test, expect } from 'bun:test';
import { cmac } from './cmac.js';
import { aes } from '../cipher/aes.js';
import { bitArray } from '../utils/bitArray.js';
import { hex } from '../../io/codec/hex.js';

const _ba = bitArray.factory();
const _hex = hex.factory();
const _aes = aes.factory();
const _cmac = cmac.factory(_ba);

const fromHex = (s) => Array.from(_ba.ui8_to_ba(_hex.toBytes(s)));
const toHex = (ba) => _hex.fromBytes(_ba.ba_to_ui8(ba));

// RFC 4493 §4 — AES-128 key
const KEY = fromHex('2b7e151628aed2a6abf7158809cf4f3c');

describe('cmac module (RFC 4493 / NIST SP 800-38B)', () => {

    test('module metadata', () => {
        expect(cmac.name).toBe('cmac');
        expect(cmac.dependencies).toEqual(['bitArray']);
    });

    // RFC 4493 §4 example values: K1, K2 derived from L = AES_K(0)
    test('subkey derivation (K1, K2 / RFC 4493 §4)', () => {
        const cipher = _aes.ttable.fn(KEY);
        const L = cipher.encrypt([0, 0, 0, 0]);
        expect(toHex(L)).toBe('7df76b0c1ab899b33e42f047b91b546f');
        const K1 = _cmac._internal.dbl(L);
        const K2 = _cmac._internal.dbl(K1);
        expect(toHex(K1)).toBe('fbeed618357133667c85e08f7236a8de');
        expect(toHex(K2)).toBe('f7ddac306ae266ccf90bc11ee46d513b');
    });

    describe('RFC 4493 §4 test vectors (AES-128)', () => {
        const cipher = () => _aes.ttable.fn(KEY);

        test('Example 1: empty message', () => {
            expect(toHex(_cmac.mac(cipher(), []))).toBe(
                'bb1d6929e95937287fa37d129b756746'
            );
        });

        test('Example 2: 16-byte message (one block)', () => {
            const msg = fromHex('6bc1bee22e409f96e93d7e117393172a');
            expect(toHex(_cmac.mac(cipher(), msg))).toBe(
                '070a16b46b4d4144f79bdd9dd04a287c'
            );
        });

        test('Example 3: 40-byte message (incomplete final block)', () => {
            const msg = fromHex(
                '6bc1bee22e409f96e93d7e117393172a' +
                'ae2d8a571e03ac9c9eb76fac45af8e51' +
                '30c81c46a35ce411'
            );
            expect(toHex(_cmac.mac(cipher(), msg))).toBe(
                'dfa66747de9ae63030ca32611497c827'
            );
        });

        test('Example 4: 64-byte message (4 complete blocks)', () => {
            const msg = fromHex(
                '6bc1bee22e409f96e93d7e117393172a' +
                'ae2d8a571e03ac9c9eb76fac45af8e51' +
                '30c81c46a35ce411e5fbc1191a0a52ef' +
                'f69f2445df4f9b17ad2b417be66c3710'
            );
            expect(toHex(_cmac.mac(cipher(), msg))).toBe(
                '51f0bebf7e3b9d92fc49741779363cfe'
            );
        });
    });

    describe('verify', () => {
        test('accepts a correct tag', () => {
            const cipher = _aes.ttable.fn(KEY);
            const tag = _cmac.mac(cipher, []);
            expect(_cmac.verify(_aes.ttable.fn(KEY), [], tag)).toBe(true);
        });

        test('rejects a tampered tag', () => {
            const cipher = _aes.ttable.fn(KEY);
            const tag = _cmac.mac(cipher, []);
            tag[0] ^= 1;
            expect(_cmac.verify(_aes.ttable.fn(KEY), [], tag)).toBe(false);
        });
    });
});


