describe('cmac - ACVP CMAC-AES-1.0', () => {

    describe('gen (MAC generation, 81 sub-sampled)', () => {
        test.each(CMAC_GEN)('tgId=$tg tcId=$tc (AES-$kl, msgLen=$ml, macLen=$mac_l)', (v) => {
            const key = fromHex(v.key);
            const msg = v.msg === '' ? [] : fromHex(v.msg);
            const tag = _cmac.mac(_aes.ttable.fn(key), msg);
            const tagTrunc = _ba.clamp(tag, v.mac_l);
            expect(toHex(tagTrunc)).toBe(v.mac.toLowerCase());
        });
    });

    describe('ver (MAC verification, 108 sub-sampled, includes negative cases)', () => {
        test.each(CMAC_VER)('tgId=$tg tcId=$tc (AES-$kl, msgLen=$ml, macLen=$mac_l, pass=$pass)', (v) => {
            const key = fromHex(v.key);
            const msg = v.msg === '' ? [] : fromHex(v.msg);
            const expectedTag = _cmac.mac(_aes.ttable.fn(key), msg);
            const expectedTrunc = _ba.clamp(expectedTag, v.mac_l);
            const providedTrunc = _ba.clamp(fromHex(v.mac), v.mac_l);
            const match = _ba.equal(expectedTrunc, providedTrunc);
            expect(match).toBe(v.pass);
        });
    });

});


// ============================================================================
// Iteration D3 of the FIPS 140-3 upgrade plan
// ----------------------------------------------------------------------------
// (1) TDES rejection: `_checkBlockSize` rejects any PRF with
//     `blockSize !== 16` (SP 800-131A §2.4 + SP 800-38B §5.1).
// (2) `truncatedMac` / `truncatedVerify`: enforcement of SP 800-38B §6.4
//     (`tagLen ∈ [32, 128]` bits in increments of 8).
// ============================================================================

describe('cmac - iteration D3: TDES guard + truncatedMac', () => {

    const KEY = fromHex('2b7e151628aed2a6abf7158809cf4f3c');

    test('mac rejects PRF with blockSize=8 (TDES)', () => {
        const fakeTdes = {
            blockSize: 8,
            encrypt: () => [0, 0]   // 2-word output = 8 bytes
        };
        expect(_cmac.mac(fakeTdes, [])).toBe(false);
    });

    test('verify rejects PRF with blockSize=8 (TDES)', () => {
        const fakeTdes = {
            blockSize: 8,
            encrypt: () => [0, 0]
        };
        expect(_cmac.verify(fakeTdes, [], [0, 0, 0, 0])).toBe(false);
    });

    test('AES PRF without explicit blockSize accepted (back-compat)', () => {
        const tag = _cmac.mac(_aes.ttable.fn(KEY), []);
        expect(tag).not.toBe(false);
        expect(_ba.bitLength(tag)).toBe(128);
    });

    test('AES PRF with explicit blockSize=16 (defensive) accepted', () => {
        const inner = _aes.ttable.fn(KEY);
        const wrapped = { blockSize: 16, encrypt: (d) => inner.encrypt(d) };
        const tag = _cmac.mac(wrapped, []);
        expect(tag).not.toBe(false);
    });

    test('truncatedMac with tagLen=32 (SP 800-38B §6.4 minimum) returns 32 bits', () => {
        const tag = _cmac.truncatedMac(_aes.ttable.fn(KEY), [], 32);
        expect(tag).not.toBe(false);
        expect(_ba.bitLength(tag)).toBe(32);
    });

    test('truncatedMac with tagLen=64, 96, 128 all accepted', () => {
        for (const tlen of [64, 96, 128]) {
            const tag = _cmac.truncatedMac(_aes.ttable.fn(KEY), [], tlen);
            expect(_ba.bitLength(tag)).toBe(tlen);
        }
    });

    test('truncatedMac rejects tagLen < 32 (SP 800-38B §6.4 floor)', () => {
        for (const tlen of [0, 1, 8, 16, 24, 31]) {
            expect(_cmac.truncatedMac(_aes.ttable.fn(KEY), [], tlen)).toBe(false);
        }
    });

    test('truncatedMac rejects tagLen > 128 (CMAC output ceiling)', () => {
        for (const tlen of [129, 256, 1000]) {
            expect(_cmac.truncatedMac(_aes.ttable.fn(KEY), [], tlen)).toBe(false);
        }
    });

    test('truncatedMac rejects non-integer / non-numeric tagLen', () => {
        expect(_cmac.truncatedMac(_aes.ttable.fn(KEY), [], 32.5)).toBe(false);
        expect(_cmac.truncatedMac(_aes.ttable.fn(KEY), [], '32')).toBe(false);
        expect(_cmac.truncatedMac(_aes.ttable.fn(KEY), [], null)).toBe(false);
        expect(_cmac.truncatedMac(_aes.ttable.fn(KEY), [], undefined)).toBe(false);
    });

    test('truncatedMac is a prefix of full mac (clamp coherence)', () => {
        const msg = fromHex('6bc1bee22e409f96e93d7e117393172a');
        const fullTag = _cmac.mac(_aes.ttable.fn(KEY), msg);
        for (const tlen of [32, 48, 64, 96, 128]) {
            const truncTag = _cmac.truncatedMac(_aes.ttable.fn(KEY), msg, tlen);
            const ref = _ba.clamp(fullTag, tlen);
            expect(_ba.equal(truncTag, ref)).toBe(true);
        }
    });

    test('truncatedVerify accepts a correctly-truncated tag', () => {
        const msg = fromHex('6bc1bee22e409f96e93d7e117393172a');
        const tag = _cmac.truncatedMac(_aes.ttable.fn(KEY), msg, 64);
        expect(_cmac.truncatedVerify(_aes.ttable.fn(KEY), msg, tag, 64)).toBe(true);
    });

    test('truncatedVerify rejects a tampered tag', () => {
        const msg = fromHex('6bc1bee22e409f96e93d7e117393172a');
        const tag = _cmac.truncatedMac(_aes.ttable.fn(KEY), msg, 64);
        // Flip one bit in the tag
        const tampered = tag.slice();
        tampered[0] ^= 1;
        expect(_cmac.truncatedVerify(_aes.ttable.fn(KEY), msg, tampered, 64)).toBe(false);
    });

    test('truncatedVerify rejects with bad tagLen (delegated)', () => {
        expect(_cmac.truncatedVerify(_aes.ttable.fn(KEY), [], [0], 16)).toBe(false);
        expect(_cmac.truncatedVerify(_aes.ttable.fn(KEY), [], [0], 200)).toBe(false);
    });
});
